using System;
using System.IO;
using System.Linq;
using System.Xml.Linq;
using CircuitoStudio;
class DiagramAppearanceTests {
 static int n;static void Check(bool b,string text){n++;if(!b)throw new Exception(text);}
 static void Reject(Action action){try{action();}catch(InvalidDataException){n++;return;}throw new Exception("Invalid diagram setting accepted");}
 static void Main(){string dir=Path.Combine(Path.GetTempPath(),"diagram-appearance-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{
  var project=Project.CreateSample();var board=project.Boards[0];var c=board.Circuits[0];var before=Engineering.Analyze(project);Check(CircuitVisuals.Caption(c)==c.Id+" · "+c.Name,"Default label");Check(CircuitVisuals.Resolve(c)==DiagramSymbol.Lampada&&CircuitVisuals.Resolve(board.Circuits[1])==DiagramSymbol.Tomada,"Automatic load symbols");
  string label="Área <Q> & motor \"Ω\" "+new string('x',100);c.DiagramLabel=label;c.DrawingSymbol=DiagramSymbol.Motor;c.DiagramX=450;c.DiagramY=500;project.DrawingTheme=DiagramTheme.Monocromatico;var after=Engineering.Analyze(project);Check(before.TotalKw==after.TotalKw&&before.TotalKvar==after.TotalKvar&&before.For(c).CurrentA==after.For(c).CurrentA&&before.For(c).VoltageDropV==after.For(c).VoltageDropV,"Appearance does not change electrical results");Check(c.Kind=="Iluminação"&&c.Name=="Iluminação"&&c.Id=="C1","Symbol selection does not change load type/name/ID");
  string saved=Path.Combine(dir,"diagram.circuito");project.Save(saved);var loaded=Project.Load(saved);Check(loaded.DrawingTheme==DiagramTheme.Monocromatico&&loaded.Boards[0].Circuits[0].DrawingSymbol==DiagramSymbol.Motor&&loaded.Boards[0].Circuits[0].DiagramLabel==label,"Appearance survives save/load Unicode");
  string svg=Path.Combine(dir,"diagram.svg");Exports.Svg(project,board,svg);XNamespace ns="http://www.w3.org/2000/svg";var xml=XDocument.Load(svg);var circuitGroup=xml.Descendants(ns+"g").Single(g=>(string)g.Attribute("data-circuit-id")==c.Id);Check(circuitGroup.Element(ns+"title").Value==label,"Full untruncated label retained in SVG metadata");Check(circuitGroup.Descendants(ns+"g").Single(g=>(string)g.Attribute("class")=="load-symbol").Attribute("data-symbol").Value=="Motor","Chosen symbol exported");Check(circuitGroup.Descendants(ns+"circle").Any(e=>(string)e.Attribute("cx")=="450"&&(string)e.Attribute("cy")=="605"&&(string)e.Attribute("r")=="15"),"Moved symbol geometry preserved in SVG");Check(xml.Descendants().Attributes("stroke").All(a=>a.Value.Equals("Black",StringComparison.OrdinalIgnoreCase)||a.Value=="none"),"Monochromatic strokes");Check(!File.ReadAllText(svg).Contains("<Q>"),"Label escaped as XML text");
  foreach(DiagramSymbol symbol in Enum.GetValues(typeof(DiagramSymbol))){if(symbol==DiagramSymbol.Automatico)continue;c.DrawingSymbol=symbol;Exports.Svg(project,board,svg);xml=XDocument.Load(svg);var group=xml.Descendants(ns+"g").First(g=>(string)g.Attribute("class")=="load-symbol");Check((string)group.Attribute("data-symbol")==symbol.ToString()&&group.Descendants(ns+"circle").Any(),"All selectable vector symbols export: "+symbol);}
  c.DrawingSymbol=(DiagramSymbol)999;Reject(delegate{project.Validate();});c.DrawingSymbol=DiagramSymbol.Automatico;c.DiagramLabel=new string('x',201);Reject(delegate{project.Validate();});c.DiagramLabel="";project.DrawingTheme=(DiagramTheme)999;Reject(delegate{project.Validate();});project.DrawingTheme=DiagramTheme.Colorido;Check(CircuitVisuals.Caption(c)==c.Id+" · "+c.Name,"Clearing label restores default");Console.WriteLine("PASS: "+n+" diagram appearance assertions");
 }finally{Directory.Delete(dir,true);}}
}
